select jsonb_build_object(
 'tables',(select jsonb_agg(t order by t.schema,t.name) from (select n.nspname as schema,c.relname as name,c.relrowsecurity as rls,c.relforcerowsecurity as forced_rls from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','credit_internal','lesson_ops','library_internal','workspace_internal') and c.relkind='r')t),
 'columns',(select jsonb_agg(t order by t.table_schema,t.table_name,t.ordinal_position) from (select table_schema,table_name,column_name,ordinal_position,data_type,udt_name,is_nullable,column_default from information_schema.columns where table_schema in ('public','private','credit_internal','lesson_ops','library_internal','workspace_internal'))t),
 'constraints',(select jsonb_agg(t order by t.schema,t.table_name,t.name) from (select n.nspname as schema,c.relname as table_name,con.conname as name,pg_get_constraintdef(con.oid) as definition from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','credit_internal','lesson_ops','library_internal','workspace_internal') and con.contype <> 'n')t),
 'indexes',(select jsonb_agg(t order by t.schemaname,t.indexname) from (select schemaname,indexname,indexdef from pg_indexes where schemaname in ('public','private','credit_internal','lesson_ops','library_internal','workspace_internal'))t),
 'functions',(select jsonb_agg(t order by t.schema,t.name,t.arguments) from (select n.nspname as schema,p.proname as name,pg_get_function_identity_arguments(p.oid) as arguments,replace(pg_get_functiondef(p.oid),E'\r\n',E'\n') as definition,p.proacl::text as acl from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private','credit_internal','lesson_ops','library_internal','workspace_internal') and p.prokind='f' and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e'))t),
 'policies',(select jsonb_agg(t order by t.schemaname,t.tablename,t.policyname) from (select schemaname,tablename,policyname,permissive,roles,cmd,qual,with_check from pg_policies where schemaname in ('public','private','credit_internal','lesson_ops','library_internal','workspace_internal'))t)
) as catalog;
